"use strict";(globalThis.webpackChunkp_vs_np_docs=globalThis.webpackChunkp_vs_np_docs||[]).push([[9007],{26175(e){e.exports=JSON.parse('{"tag":{"label":"vertex-cover","permalink":"/azeon/p-vs-np/tags/vertex-cover","allTagsPath":"/azeon/p-vs-np/tags","count":3,"items":[{"id":"heuristics/approximating-vertex-cover","title":"Approximating Vertex Cover","description":"Back to the cameras from Posts 11 and 16. Pick any unwatched road and put cameras on both ends. Repeat. That\'s the whole algorithm, it\'s never worse than twice the best, and the proof fits in four lines.","permalink":"/azeon/p-vs-np/heuristics/approximating-vertex-cover"},{"id":"np-completeness/independent-set","title":"The Independent Set Problem","description":"I have used Independent Set as a stepping stone twice without ever proving it is hard. Today I pay that debt, once the lazy way and once the honest way, straight from 3-SAT.","permalink":"/azeon/p-vs-np/np-completeness/independent-set"},{"id":"np-completeness/vertex-cover","title":"The Vertex Cover Problem","description":"Back in Post 11 I used cameras on roads to explain what a reduction is. I never proved that problem was NP-Complete. Today I finally do, and it takes almost no new work.","permalink":"/azeon/p-vs-np/np-completeness/vertex-cover"}],"unlisted":false}}')}}]);